def find_all_evens(numbers):
    result = []
    for n in numbers:
        if n % 2 == 0:
            result.append(n)
        return result

print(find_all_evens([1, 2, 4, 6, 7]))

def process_scores(scores):
    passing = []
    for score in scores:
        if score >= 60:
            passing.append(score)
    print(f'Passing: {passing}')
    return passing

def clamp(value, minimum, maximum):
    if value < minimum:
        return minimum
    if value > maximum:
        return maximum
    return value

print(clamp(15, 0, 10))
